with cte0 (mq_id,mq_sortInt,mq_sortTs,mq_ranking) as (select nse1_0.id,nse1_0.sort_int,nse1_0.sort_ts,row_number() over(partition by nse1_0.sort_int order by nse1_0.sort_ts desc,nse1_0.id) from nullable_sort_rows nse1_0 where nse1_0.sort_int is not null and nse1_0.sort_ts is not null) select cte01_0.mq_id,cte01_0.mq_sortInt,cte01_0.mq_sortTs,cte01_0.mq_ranking from cte0 cte01_0 where cte01_0.mq_ranking<=? order by 2,4
